package com.sodi.metareports.client; import com.sodi.metareports.audit.AuditService; import com.sodi.metareports.client.dto.ClientForm; import com.sodi.metareports.client.entity.Client; import com.sodi.metareports.client.repository.ClientRepository; import java.util.*; import org.springframework.dao.DataIntegrityViolationException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class ClientService { private final ClientRepository repo; private final AuditService audit; public ClientService(ClientRepository r,AuditService a){repo=r;audit=a;}
 @Transactional public Client create(ClientForm f){String code=f.getCode().trim().toUpperCase();if(repo.existsByCodeIgnoreCase(code))throw new DataIntegrityViolationException("Client code already exists");Client c=new Client();apply(c,f,code);Client saved=repo.save(c);audit.record("CLIENT_CREATE","Client",saved.getId().toString(),"Client created",null,Map.of("code",saved.getCode(),"name",saved.getCommercialName()));return saved;}
 @Transactional public Client update(UUID id,ClientForm f){Client c=get(id);String oldName=c.getCommercialName();apply(c,f,f.getCode().trim().toUpperCase());Client saved=repo.save(c);audit.record("CLIENT_UPDATE","Client",id.toString(),"Client updated",Map.of("name",oldName),Map.of("name",saved.getCommercialName()));return saved;}
 @Transactional public void toggle(UUID id){Client c=get(id);c.setActive(!c.isActive());if(!c.isActive())c.setStatus(com.sodi.metareports.client.entity.ClientStatus.INACTIVE);audit.record("CLIENT_STATUS","Client",id.toString(),"Client active state changed",null,Map.of("active",c.isActive()));}
 public Client get(UUID id){return repo.findById(id).orElseThrow(()->new NoSuchElementException("Client not found"));}
 private void apply(Client c,ClientForm f,String code){c.setCode(code);c.setCommercialName(f.getCommercialName().trim());c.setLegalName(f.getLegalName());c.setDescription(f.getDescription());c.setStatus(f.getStatus());c.setPrimaryCurrency(f.getPrimaryCurrency().trim().toUpperCase());c.setTimezone(f.getTimezone().trim());c.setActive(f.getStatus()!=com.sodi.metareports.client.entity.ClientStatus.INACTIVE&&f.getStatus()!=com.sodi.metareports.client.entity.ClientStatus.ARCHIVED);}}
